+    /** Keep only minimal witness sets (a superset adds no new justification). */
+    private fun minimal(ws: Set<Set<String>>): Set<Set<String>> =
+        ws.filter { w -> ws.none { o -> o != w && w.containsAll(o) } }.toSet()
